const $=s=>document.querySelector(s), app=$('#app');
const categories=['Все','Иммунитет','Основы микробиологии','Диагностика','Инфекции'];
const custom=[
{match:'неспецифический иммунитет',simple:'Представь организм крепостью. Кожа и слизистые — стены, слёзы и лизоцим — защитные вещества, фагоциты — патруль, а комплемент — система сигнализации и атаки. Эта защита срабатывает быстро и не требует заранее узнавать конкретного врага.',scientific:'Врождённый (неспецифический) иммунитет объединяет анатомические барьеры, растворимые медиаторы (лизоцим, комплемент), клеточные механизмы (фагоциты, NK-клетки) и воспалительный ответ. Комплемент может активироваться классическим, лектиновым и альтернативным путями; итоговые эффекты включают опсонизацию, воспаление и образование мембраноатакующего комплекса.',steps:['🧱|Кожа и слизистые','🧪|Лизоцим и комплемент','🛡️|Фагоцитоз','✨|Устранение угрозы'],q:[['Что относится к первой линии врождённой защиты?',['Неповреждённая кожа','Иммунологическая память','Антитела после вакцинации'],0,'Кожа физически препятствует проникновению микробов.'],['Как действует лизоцим?',['Разрушает пептидогликан клеточной стенки бактерий','Синтезирует антитела','Создаёт споры'],0,'Лизоцим расщепляет связи в пептидогликане, особенно у чувствительных бактерий.'],['Что делает комплемент?',['Помогает опсонизации и лизису','Образует бактериальные споры','Создаёт антибиотики'],0,'Белки комплемента помогают распознавать, привлекать клетки и повреждать мембраны.']]},
{match:'дыхание клетки',simple:'Микробам нужна энергия. Одни используют кислород, другие живут без него, а третьи могут переключаться. Как электростанция, клетка выбирает доступный способ получения энергии.',scientific:'По отношению к O₂ выделяют облигатных аэробов, облигатных анаэробов, факультативных анаэробов, аэротолерантных анаэробов и микроаэрофилов. Аэробное дыхание использует O₂ как конечный акцептор электронов; при анаэробном дыхании используются другие акцепторы, а брожение отличается механизмом регенерации переносчиков электронов.',steps:['🌬️|Есть кислород','⚙️|Электрон-транспортная цепь','⚡|Образование АТФ'],q:[['Кто способен расти с кислородом и без него?',['Факультативный анаэроб','Облигатный аэроб','Облигатный анаэроб'],0,'Факультативные анаэробы переключают энергетический обмен в зависимости от условий.'],['Конечный акцептор электронов при аэробном дыхании?',['Кислород','Глюкоза','ДНК'],0,'В аэробной дыхательной цепи конечный акцептор электронов — O₂.']]},
{match:'инфекция, инфекционный',simple:'Заражение — это не всегда болезнь. Микроб может попасть в организм, но симптомы появятся только при определённых условиях. Важно различать сам факт взаимодействия с возбудителем, процесс и клиническую болезнь.',scientific:'Инфекционный процесс — взаимодействие возбудителя с восприимчивым макроорганизмом в определённых условиях. Инфекционная болезнь — клинически выраженная форма этого процесса. Выделяют экзогенные и эндогенные инфекции, моно- и смешанные, острые и хронические, манифестные и бессимптомные.',steps:['🦠|Контакт с возбудителем','🚪|Проникновение','🔁|Размножение','🩺|Исход / симптомы'],q:[['Всегда ли инфицирование сопровождается симптомами?',['Нет','Да','Только у животных'],0,'Инфекция может протекать бессимптомно.'],['Что означает смешанная инфекция?',['Участие нескольких возбудителей','Повторное заражение тем же микробом','Только вирусная инфекция'],0,'Смешанная инфекция вызывается несколькими микроорганизмами.']]},
{match:'питание метаболизм',simple:'Бактерии похожи на мини-фабрики: получают сырьё, превращают его в энергию и строительные детали. Одни питаются готовыми органическими веществами, другие используют CO₂.',scientific:'Метаболизм включает катаболизм (получение энергии и предшественников) и анаболизм (биосинтез). По источнику углерода различают автотрофов и гетеротрофов; по источнику энергии — фототрофов и хемотрофов. Эти классификации описывают разные свойства и могут комбинироваться.',steps:['🍽️|Питательные вещества','🔧|Катаболизм','⚡|АТФ','🧬|Анаболизм'],q:[['Что такое катаболизм?',['Распад веществ с высвобождением энергии','Синтез сложных молекул','Деление клетки'],0,'Катаболические реакции расщепляют вещества и обеспечивают клетку энергией.'],['Основной источник углерода автотрофов?',['CO₂','Готовые белки','Только глюкоза'],0,'Автотрофы используют неорганический углерод, прежде всего CO₂.']]},
{match:'стерилизац',simple:'Дезинфекция уменьшает количество опасных микробов, а стерилизация уничтожает все жизнеспособные микроорганизмы, включая бактериальные споры. Выбор метода зависит от материала.',scientific:'Стерилизация — валидированный процесс устранения жизнеспособных микроорганизмов, включая споры. Влажный жар в автоклаве обеспечивает эффективную передачу тепла; сухожаровые, фильтрационные и иные методы применяются с учётом свойств объекта. Конкретный режим определяется оборудованием и протоколом.',steps:['🧫|Объект','🌡️|Подходящий метод','⏱️|Контроль процесса','✅|Стерильный материал'],q:[['Что отличает стерилизацию от дезинфекции?',['Устранение всех жизнеспособных микроорганизмов, включая споры','Только мытьё водой','Удаление лишь видимой грязи'],0,'Стерилизация предъявляет более строгие требования, чем дезинфекция.']]},
{match:'туберкулез',simple:'Микобактерии туберкулёза отличаются необычной богатой липидами клеточной оболочкой. Из-за неё для окраски и диагностики нужны специальные методы.',scientific:'Mycobacterium tuberculosis complex — кислотоустойчивые бактерии с богатой миколовыми кислотами оболочкой. Для диагностики применяют микроскопию кислотоустойчивых бактерий, молекулярные тесты и культуральные исследования; выбор алгоритма зависит от вида пациента, образца и локальных рекомендаций.',steps:['🧪|Образец','🔬|Микроскопия','🧬|Молекулярный тест','📋|Интерпретация'],q:[['Почему микобактерии кислотоустойчивы?',['Из-за липидов и миколовых кислот в клеточной оболочке','Из-за отсутствия ДНК','Из-за жгутиков'],0,'Особая липидная клеточная оболочка определяет кислотоустойчивость.']]},
{match:'столбняка и ботулизма',simple:'Столбняк и ботулизм связаны с нейротоксинами клостридий, но действуют по-разному: при столбняке преобладают спазмы, при ботулизме — вялый паралич.',scientific:'Clostridium tetani вырабатывает тетаноспазмин, нарушающий высвобождение тормозных медиаторов, что ведёт к спастическому параличу. Ботулинический нейротоксин Clostridium botulinum блокирует высвобождение ацетилхолина в нервно-мышечном синапсе и вызывает вялый паралич.',steps:['🦠|Clostridium','🧪|Нейротоксин','🧠|Нервный синапс','⚠️|Нарушение движения'],q:[['Какой тип паралича характерен для ботулизма?',['Вялый','Спастический','Паралича не бывает'],0,'Ботулотоксин препятствует высвобождению ацетилхолина и вызывает вялый паралич.'],['Какой тип паралича характерен для столбняка?',['Спастический','Вялый','Только сенсорный'],0,'Тетаноспазмин нарушает тормозную передачу и вызывает мышечные спазмы.']]},
{match:'антибиотик',simple:'Антибиотики мешают бактериям строить стенку, производить белки или выполнять другие важные функции. Против вирусов обычные антибактериальные препараты не работают.',scientific:'Антибактериальные препараты классифицируют по мишеням: синтез клеточной стенки, белка, нуклеиновых кислот, фолатный обмен и целостность мембраны. Эффективность зависит от чувствительности возбудителя, фармакокинетики и локализации инфекции.',steps:['💊|Препарат','🎯|Молекулярная мишень','⛔|Подавление роста'],q:[['На что действуют β-лактамные антибиотики?',['Синтез клеточной стенки','Синтез вирусного капсида','Ядро эритроцита'],0,'β-лактамы нарушают образование пептидогликана клеточной стенки.']]}
];
const bad=/^(В зависимости от числа|По происхождению|По выраженности|Жив-го происх|Разрушающие рибосом|Огромная скорость|На обезжиренное|Физиологический раствор|Антиген|Агглютиноген|Исследуемое молоко)/i;
const topics=TOPICS.filter(t=>!bad.test(t.title)&&t.body.length>130).map((t,i)=>({...t,uid:i,custom:custom.find(c=>t.title.toLowerCase().includes(c.match))}));
let filter='Все',query='',current=null,mode='simple',test=[],idx=0,score=0,locked=false,review=[];
let bookmarks={},difficult={},flashIndex=0,flashShown=false,spaced={};try{bookmarks=JSON.parse(localStorage.getItem('micro-bookmarks')||'{}');difficult=JSON.parse(localStorage.getItem('micro-difficult')||'{}');spaced=JSON.parse(localStorage.getItem('micro-spaced')||'{}')}catch(e){}
function persistStudy(){try{localStorage.setItem('micro-bookmarks',JSON.stringify(bookmarks));localStorage.setItem('micro-difficult',JSON.stringify(difficult));localStorage.setItem('micro-spaced',JSON.stringify(spaced))}catch(e){}}
function excerpts(t){let raw=t.body.replace(/\s+/g,' ').replace(/(?:^|\s)(?:\d+[.)]|[-•])\s+/g,' ');let arr=raw.split(/(?<=[.!?])\s+(?=[А-ЯA-ZЁ])/).map(x=>x.trim()).filter(x=>x.length>=65&&x.length<=310&&!/https?:|рисунок|таблица/i.test(x));return [...new Set(arr)].slice(0,12)}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress={};try{progress=JSON.parse(localStorage.getItem('micro-progress')||'{}')}catch(e){}
function save(){try{localStorage.setItem('micro-progress',JSON.stringify(progress))}catch(e){}}
function baseHome(){current=null;const done=topics.filter(t=>progress[t.uid]).length;app.innerHTML=`<div class="hero"><div><div class="eyebrow">Твоя лаборатория знаний</div><h1>Микробиология.<br>Понять, а не зазубрить.</h1><p class="muted">Теория на двух уровнях сложности, интерактивные модели, тесты с разбором ошибок и прогресс обучения. По материалам экзаменационных билетов.</p><div class="stats"><div class="stat"><strong>${topics.length}</strong><small>тем из PDF</small></div><div class="stat"><strong>${done}</strong><small>тем пройдено</small></div><div class="stat"><strong>${Math.round(done/topics.length*100)}%</strong><small>прогресс</small></div></div></div><div class="panel hero-art"><div class="microbe"></div></div></div><div class="study-shortcuts"><button class="btn" id="showbookmarks">☆ Избранное <b>${Object.values(bookmarks).filter(Boolean).length}</b></button><button class="btn" id="showdifficult">↻ Повторить сложное <b>${Object.values(difficult).filter(Boolean).length}</b></button><button class="btn" id="exportprogress">↓ Сохранить прогресс</button><label class="btn import-label">↑ Восстановить <input type="file" id="importprogress" accept="application/json" hidden></label></div><h2>Библиотека тем</h2><div class="toolbar"><input id="search" class="search" placeholder="⌕ Найти тему или термин…" value="${esc(query)}">${categories.map(c=>`<button class="chip ${filter===c?'active':''}" data-cat="${c}">${c}</button>`).join('')}</div><div id="topiclist"></div><p class="source">Основа: «Микра билеты с пояснениями» (89 страниц). Дополнительная справка: <a target="_blank" href="https://openstax.org/books/microbiology/pages/1-introduction">OpenStax Microbiology</a>. Учебный материал требует проверки преподавателем перед экзаменом.</p>`;$('#search').oninput=e=>{query=e.target.value;drawList()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{filter=b.dataset.cat;home()});$('#showbookmarks').onclick=()=>{filter='Избранное';drawList()};$('#showdifficult').onclick=()=>{filter='Сложное';drawList()};$('#exportprogress').onclick=exportProgress;$('#importprogress').onchange=importProgress;drawList()}
function drawList(){const items=topics.filter(t=>(filter==='Все'||t.section===filter||(filter==='Избранное'&&bookmarks[t.uid])||(filter==='Сложное'&&difficult[t.uid]))&&(t.title+' '+t.body.slice(0,2000)).toLowerCase().includes(query.toLowerCase()));$('#topiclist').innerHTML=items.length?`<div class="tiles">${items.map(t=>`<button class="tile" data-id="${t.uid}"><div class="number">${progress[t.uid]?'✓ ПРОЙДЕНО':'ТЕМА '+String(t.uid+1).padStart(2,'0')}</div><h3>${esc(t.title)}</h3><small>${esc(t.section)} · ${t.custom?'тест с выбором':'карточки + самопроверка'}</small></button>`).join('')}</div>`:'<div class="empty">Ничего не найдено. Попробуйте другой запрос.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>lesson(topics.find(t=>t.uid==b.dataset.id)))}
function exportProgress(){const blob=new Blob([JSON.stringify({version:5,progress,bookmarks,difficult,spaced,ticketProgress,bankState,exported:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='micro-lab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importProgress(e){const f=e.target.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!d||typeof d!=='object'||typeof d.progress!=='object')throw Error();progress=d.progress||{};bookmarks=d.bookmarks||{};difficult=d.difficult||{};spaced=d.spaced||{};ticketProgress=d.ticketProgress||{};if(d.bankState&&typeof d.bankState==='object'){bankState=d.bankState;saveBank()}saveTicketProgress();save();persistStudy();home();alert('Прогресс восстановлен')}catch(err){alert('Не удалось прочитать файл прогресса')}}
function simpleText(t){if(t.custom)return t.custom.simple;const lines=t.body.split(/(?<=[.!?])\s+/).filter(x=>x.length>35&&x.length<400).slice(0,7);return `Главная идея темы «${t.title}» — понять ключевые определения и их взаимосвязь. Ниже основные положения исходного конспекта:\n\n`+lines.join('\n\n')+'\n\nДля экзамена важно уметь объяснить термины своими словами и привести пример.'}
function scientificText(t){return t.custom?t.custom.scientific+'\n\nИз исходного конспекта:\n'+t.body.slice(0,2400):t.body}
function diagram(t){let steps=t.custom?.steps||['🔎|Объект изучения','🧪|Основные признаки','🧠|Объяснение механизма','✓|Вывод'];return `<div class="diagram"><div class="diagram-title">◈ ${t.custom?'Схема механизма':'План изучения темы'}: ${esc(t.title)}</div><div class="diagram-flow">${steps.map((v,i)=>{let [emoji,label]=v.split('|');return `<div class="node"><b>${emoji}</b><span>${esc(label)}</span></div>`}).join('')}</div><p class="muted small" style="margin-top:16px">Нажимайте на этапы, чтобы выделить их и проследить последовательность.</p></div>`}
function modelKind(t){const n=t.title.toLowerCase();if(/иммунитет|фагоцит|комплемент/.test(n))return 'immune';if(/дыхани|метаболизм|питани|типу питания/.test(n))return 'energy';if(/диагностик|отбор материала|реакци|рп по асколи|ра на стекле/.test(n))return 'lab';if(/инфекци|передачи/.test(n))return 'infection';return null}
const modelLibrary={
immune:{title:'Как организм обезвреживает бактерию',stages:[['Барьер','Микроорганизм приближается к защитному барьеру кожи или слизистой.'],['Распознавание','После преодоления барьера клетки врождённого иммунитета распознают чужеродные структуры.'],['Фагоцитоз','Фагоцит захватывает бактерию и помещает её в фагосому.'],['Разрушение','Фагосома сливается с лизосомой; бактерия разрушается.']]},
energy:{title:'От питательного вещества к АТФ',stages:[['Поступление','Питательное вещество попадает в клетку.'],['Катаболизм','Субстрат преобразуется в ходе ферментативных реакций.'],['АТФ','Часть освобождённой энергии сохраняется в форме АТФ.'],['Биосинтез','АТФ используется в энергозатратных клеточных процессах.']]},
lab:{title:'От образца к лабораторному заключению',stages:[['Образец','Материал отбирают с соблюдением требований к качеству и безопасности.'],['Исследование','К образцу применяют подходящий лабораторный метод.'],['Контроль','Контрольные образцы помогают оценить корректность исследования.'],['Заключение','Результат интерпретируют с учётом клинического контекста.']]},
infection:{title:'Как прерывается цепочка инфекции',stages:[['Источник','В источнике находится возбудитель.'],['Выделение','Возбудитель покидает источник инфекции.'],['Передача','Реализуется соответствующий механизм передачи.'],['Новый хозяин','Возбудитель достигает восприимчивого организма.']]}
};
function modelSvg(kind){const labels={immune:['Барьер','Микроб','Фагоцит','Лизосома'],energy:['Субстрат','Ферменты','АТФ','Синтез'],lab:['Образец','Анализ','Контроль','Результат'],infection:['Источник','Выделение','Передача','Хозяин']}[kind];const scene=kind==='immune'?`<path d="M0 218 Q55 197 110 218 T220 218 T330 218 T440 218 T550 218 T660 218" fill="none" stroke="#67d6ba" stroke-width="16" opacity=".85"/><path d="M0 241H660" stroke="#67d6ba" stroke-width="2" stroke-dasharray="8 8" opacity=".45"/><g class="viz-cell"><circle cx="468" cy="145" r="70" fill="#275d7a" stroke="#8cc9f3" stroke-width="5"/><path d="M443 132Q464 106 493 139Q485 169 452 171Z" fill="#9e81dc" opacity=".8"/><circle cx="487" cy="167" r="18" fill="#2d415f" stroke="#f7c88c" stroke-width="3"/></g><g class="viz-microbe"><rect x="115" y="88" width="62" height="37" rx="19" fill="#f49c77" stroke="#ffce9a" stroke-width="3"/><path d="M129 94v25m16-26v26m16-25v25" stroke="#9c4d4b" stroke-width="3"/></g><g class="viz-particles"><circle cx="458" cy="146" r="7" fill="#f49c77"/><circle cx="478" cy="156" r="6" fill="#f49c77"/><circle cx="468" cy="135" r="5" fill="#f49c77"/></g>`:kind==='energy'?`<rect x="90" y="50" width="470" height="230" rx="110" fill="#193b50" stroke="#78d8ce" stroke-width="5"/><g class="viz-microbe"><polygon points="120,142 148,110 186,121 201,157 164,179 129,168" fill="#f6b86e" stroke="#ffdfaa" stroke-width="4"/></g><g class="viz-cell"><circle cx="350" cy="148" r="62" fill="#30567b" stroke="#8cc9f3" stroke-width="4"/><path d="M327 133l24-21 24 23-25 30Z" fill="#b6a0f1"/></g><g class="viz-particles"><circle cx="435" cy="111" r="22" fill="#f7d66b"/><text x="435" y="117" fill="#20344a" text-anchor="middle" font-size="16" font-weight="900">ATP</text><circle cx="492" cy="174" r="22" fill="#f7d66b"/><text x="492" y="180" fill="#20344a" text-anchor="middle" font-size="16" font-weight="900">ATP</text></g>`:kind==='lab'?`<g class="viz-microbe"><path d="M130 76v120q0 40 35 40t35-40V76" fill="#235a72" stroke="#9cddf1" stroke-width="8"/><path d="M137 166h56v28q0 28-28 28t-28-28Z" fill="#e59b91"/><circle cx="155" cy="188" r="7" fill="#fce0a4"/><circle cx="177" cy="197" r="5" fill="#fce0a4"/></g><g class="viz-cell"><path d="M335 88v90m-28-62h56m-40-28h24m-8 90l-30 48m30-48l30 48m-80 0h100" fill="none" stroke="#9dc9f1" stroke-width="13" stroke-linecap="round"/><circle cx="335" cy="84" r="20" fill="#a99ae7"/><circle cx="335" cy="180" r="26" fill="#376789"/></g><g class="viz-particles"><rect x="445" y="93" width="110" height="150" rx="12" fill="#23435c" stroke="#8cd9c6" stroke-width="4"/><path d="M464 129h72m-72 23h72m-72 23h48" stroke="#c9e9f0" stroke-width="7" stroke-linecap="round"/><path d="M470 205l15 14 28-32" fill="none" stroke="#7de2b4" stroke-width="7"/></g>`:`<g class="viz-microbe"><circle cx="118" cy="154" r="65" fill="#275d7a" stroke="#9ac9ec" stroke-width="5"/><circle cx="118" cy="154" r="20" fill="#efaa82"/></g><path d="M205 154h230" stroke="#55758d" stroke-width="6" stroke-dasharray="12 12"/><g class="viz-particles"><circle cx="252" cy="154" r="12" fill="#ee9c80"/><circle cx="310" cy="154" r="12" fill="#ee9c80"/><circle cx="368" cy="154" r="12" fill="#ee9c80"/></g><g class="viz-cell"><circle cx="520" cy="154" r="65" fill="#275d7a" stroke="#9ac9ec" stroke-width="5"/><circle cx="520" cy="154" r="20" fill="#efaa82"/></g>`;return `<svg class="viz-svg" viewBox="0 0 660 315" role="img" aria-label="Анимированная учебная модель: ${labels.join(', ')}"><defs><marker id="viz-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#82e3d2" stroke-width="1.5"/></marker></defs>${scene}<text x="330" y="295" text-anchor="middle" class="viz-caption" id="viz-caption">${labels[0]}</text></svg>`}
function interactiveModel(t){const kind=modelKind(t);if(!kind)return '';const m=modelLibrary[kind];return `<section class="panel model-panel" id="model-view" data-kind="${kind}" data-phase="0"><div class="eyebrow">ВИЗУАЛЬНЫЙ СИМУЛЯТОР · УЧЕБНАЯ МОДЕЛЬ</div><h2>${m.title}</h2><p class="muted small">Наблюдайте, как меняются объекты на схеме. Нажмите на этап или запустите автоматическое воспроизведение.</p><div class="viz-stage">${modelSvg(kind)}<div class="viz-legend"><span>● ${kind==='immune'?'Бактерия':kind==='energy'?'Субстрат':kind==='lab'?'Материал':'Возбудитель'}</span><span>● ${kind==='immune'?'Фагоцит':kind==='energy'?'Клетка':kind==='lab'?'Метод':'Организм'}</span></div></div><div class="viz-timeline" role="group" aria-label="Выберите этап процесса">${m.stages.map((v,i)=>`<button type="button" class="viz-phase ${i===0?'selected':''}" data-phase-btn="${i}" aria-pressed="${i===0}"><small>0${i+1}</small>${v[0]}</button>`).join('')}</div><div class="model-detail" id="model-detail" aria-live="polite"><b>Этап 1. ${m.stages[0][0]}</b><p>${m.stages[0][1]}</p></div><div class="model-nav"><button class="btn" id="model-prev">← Предыдущий</button><button class="btn" id="model-play" aria-pressed="false">▶ Автовоспроизведение</button><button class="btn primary" id="model-next">Следующий →</button></div><p class="source">Упрощённая модель для понимания механизма, не масштабная симуляция и не дословная иллюстрация PDF.</p></section>`}
function wireModel(t){const root=document.querySelector('#model-view');if(!root)return;const buttons=[...root.querySelectorAll('[data-phase-btn]')],m=modelLibrary[root.dataset.kind];let at=0,timer=null;const play=root.querySelector('#model-play');function select(i){at=(i+buttons.length)%buttons.length;root.dataset.phase=String(at);buttons.forEach((b,j)=>{b.classList.toggle('selected',j===at);b.setAttribute('aria-pressed',String(j===at))});root.querySelector('#model-detail').innerHTML=`<b>Этап ${at+1}. ${m.stages[at][0]}</b><p>${m.stages[at][1]}</p>`;root.querySelector('#viz-caption').textContent=m.stages[at][0]}function stop(){if(timer)clearInterval(timer);timer=null;play.textContent='▶ Автовоспроизведение';play.setAttribute('aria-pressed','false')}buttons.forEach((b,i)=>b.onclick=()=>{stop();select(i)});root.querySelector('#model-prev').onclick=()=>{stop();select(at-1)};root.querySelector('#model-next').onclick=()=>{stop();select(at+1)};play.onclick=()=>{if(timer){stop();return}play.textContent='⏸ Пауза';play.setAttribute('aria-pressed','true');select((at+1)%4);timer=setInterval(()=>{if(!root.isConnected){stop();return}select((at+1)%4)},2400)};window.addEventListener('pagehide',stop,{once:true})}
function interactiveModelData(t){const n=t.title.toLowerCase();if(/иммунитет|фагоцит|комплемент/.test(n))return ['Кожа и слизистые препятствуют проникновению микроорганизмов.','Клетки врождённого иммунитета распознают характерные структуры микробов.','Фагоциты поглощают микроорганизмы, а система комплемента усиливает защиту.','Уничтожение возбудителя и разрешение воспалительного ответа.'];if(/дыхани|метаболизм|питани|типу питания/.test(n))return ['Клетка получает источник углерода и энергии.','Катаболические реакции высвобождают энергию и предшественники.','Энергия запасается в АТФ; механизм зависит от условий и организма.','Анаболизм использует энергию для построения клеточных компонентов.'];if(/диагностик|отбор материала|реакци|рп по асколи|ра на стекле/.test(n))return ['Выбирают подходящий материал и соблюдают правила отбора.','Исследование проводят по диагностическому алгоритму для предполагаемого возбудителя.','Оценивают контрольные пробы и качество результата.','Результат интерпретируют с учётом клинических данных и ограничений метода.'];return ['Возбудитель находится в источнике инфекции.','Возбудитель выделяется из источника определённым путём.','Реализуется соответствующий механизм передачи.','Возбудитель достигает восприимчивого организма.']}
function baseLesson(t){current=t;app.innerHTML=`<button class="back" id="back">← Все темы</button><div class="lesson-head"><div class="eyebrow">${esc(t.section)} · Урок ${t.uid+1}</div><div class="mode"><button data-mode="simple" class="${mode==='simple'?'active':''}">Простым языком</button><button data-mode="scientific" class="${mode==='scientific'?'active':''}">Научный</button></div></div><h1>${esc(t.title)}</h1><div class="study-shortcuts"><button class="btn" id="bookmark">${bookmarks[t.uid]?'★ В избранном':'☆ В избранное'}</button><button class="btn" id="markhard">${difficult[t.uid]?'✓ В списке повторения':'↻ Повторить позже'}</button><button class="btn" id="flashcards">▣ Карточки для запоминания</button><button class="btn" id="duecards">◷ Повторить по расписанию</button></div><div class="panel"><div class="eyebrow">01 / ТЕОРИЯ</div><div class="lecture" id="lecture">${esc(mode==='simple'?simpleText(t):scientificText(t))}</div>${interactiveModel(t)}<div class="callout"><b>Запомните:</b> понимание механизма важнее дословного воспроизведения. Переключите режим, чтобы увидеть формулировки исходного конспекта.</div><div class="bottom"><button class="btn primary" id="start">Перейти к проверке знаний →</button><button class="btn" id="other">Выбрать другую тему</button></div></div>`;$('#back').onclick=home;$('#other').onclick=home;$('#start').onclick=()=>startTest(t);$('#bookmark').onclick=()=>{bookmarks[t.uid]=!bookmarks[t.uid];persistStudy();lesson(t)};$('#markhard').onclick=()=>{difficult[t.uid]=!difficult[t.uid];persistStudy();lesson(t)};$('#flashcards').onclick=()=>showFlashcards(t);$('#duecards').onclick=()=>showFlashcards(t,true);wireModel(t);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;lesson(t)});document.querySelectorAll('.node').forEach(n=>n.onclick=()=>{document.querySelectorAll('.node').forEach(x=>x.style.borderColor='#4b6c85');n.style.borderColor='#7af0cf';n.style.background='#24534f'});scrollTo(0,0)}
function recallPrompt(c){const m=c.match(/^(.{12,95}?)[—–:]\s*(.{30,})/);if(m)return `Что означает «${m[1].trim()}»?`;const terms=c.match(/(?:[А-ЯЁ][а-яё]{5,}|[A-Z][a-z]{5,})/g)||[];return `Объясните основные признаки и механизм: ${terms.slice(0,3).join(' · ')||'ключевое положение темы'}`}
function scheduleCard(t,i,grade){const key=t.uid+':'+i;const old=spaced[key]||{interval:0,streak:0};const streak=grade==='easy'?old.streak+1:grade==='good'?Math.max(1,old.streak):0;const days=grade==='again'?0:grade==='good'?1:Math.min(30,Math.max(2,2**streak));spaced[key]={interval:days,streak,due:Date.now()+(grade==='again'?10*60*1000:days*86400000)};if(grade==='again')difficult[t.uid]=true;persistStudy()}
function showFlashcards(t,onlyDue=false){current=t;const cards=excerpts(t);let indices=cards.map((_,i)=>i).filter(i=>!onlyDue||!spaced[t.uid+':'+i]||spaced[t.uid+':'+i].due<=Date.now());flashIndex=0;flashShown=false;function draw(){if(!indices.length){app.innerHTML=`<button class="back" id="back">← К лекции</button><div class="panel"><h2>На сегодня всё повторено</h2><p class="muted">Карточки появятся снова по расписанию интервального повторения.</p><button class="btn primary" id="all">Показать все карточки</button></div>`;$('#back').onclick=()=>lesson(t);$('#all').onclick=()=>showFlashcards(t,false);return}const i=indices[flashIndex],c=cards[i];app.innerHTML=`<button class="back" id="back">← К лекции</button><div class="eyebrow">КАРТОЧКИ · ${flashIndex+1} / ${indices.length}</div><h1>${esc(t.title)}</h1><div class="panel flash-panel"><p class="muted small">Вспомните ответ до открытия карточки. Оценка определяет, когда она появится снова.</p><h2>${esc(recallPrompt(c))}</h2>${flashShown?`<div class="flash-answer">${esc(c)}</div>`:'<div class="flash-hidden">Попробуйте сформулировать ответ своими словами</div>'}<div class="bottom">${flashShown?`<button class="btn" id="again">↻ Повторить</button><button class="btn" id="good">✓ Вспомнил</button><button class="btn primary" id="easy">★ Легко</button>`:`<button class="btn primary" id="reveal">Показать ответ</button>`}</div><p class="source">Формулировка ответа — выдержка из загруженного конспекта.</p></div>`;$('#back').onclick=()=>lesson(t);if(!flashShown)$('#reveal').onclick=()=>{flashShown=true;draw()};else [['again','again'],['good','good'],['easy','easy']].forEach(([id,grade])=>$('#'+id).onclick=()=>{scheduleCard(t,i,grade);indices.splice(flashIndex,1);if(flashIndex>=indices.length)flashIndex=0;flashShown=false;draw()})}draw()}
function buildQuestions(t){if(t.custom)return t.custom.q.map(x=>({type:'choice',text:x[0],options:x[1],correct:x[2],why:x[3]}));return excerpts(t).slice(0,5).map((x,i)=>({type:'recall',text:'Объясните по памяти положение из конспекта (фрагмент '+(i+1)+'). Опорные слова: '+x.split(/\s+/).filter(w=>w.length>5).slice(0,3).join(' · '),why:x}))}
function startTest(t){test=buildQuestions(t).sort(()=>Math.random()-.5);idx=0;score=0;review=[];showQuestion()}
function showQuestion(){if(idx>=test.length)return finish();locked=false;let q=test[idx];if(q.type==='recall')return showRecall(q);let opts=q.options.map((o,i)=>({o,i})).sort(()=>Math.random()-.5);app.innerHTML=`<button class="back" id="back">← К теории</button><div class="eyebrow">02 / ПРОВЕРКА ЗНАНИЙ</div><h2>${esc(current.title)}</h2><div class="progress"><div style="width:${idx/test.length*100}%"></div></div><div class="question"><p class="muted small">Вопрос ${idx+1} из ${test.length} · ${q.type==='true'?'Верно или неверно':'Выберите ответ'}</p><h2>${esc(q.text)}</h2><div class="options">${opts.map(x=>`<button class="option" data-opt="${x.i}">${esc(x.o)}</button>`).join('')}</div><div id="feedback"></div><div class="bottom"><button class="btn primary" id="next" style="display:none">${idx===test.length-1?'Завершить тест':'Следующий вопрос →'}</button></div></div>`;$('#back').onclick=()=>lesson(current);document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>answer(+b.dataset.opt));$('#next').onclick=()=>{idx++;showQuestion()};scrollTo(0,0)}
function showRecall(q){app.innerHTML=`<button class="back" id="back">← К теории</button><div class="eyebrow">02 / САМОПРОВЕРКА ПО ИСХОДНОМУ КОНСПЕКТУ</div><h2>${esc(current.title)}</h2><div class="progress"><div style="width:${idx/test.length*100}%"></div></div><div class="question"><p class="muted small">Задание ${idx+1} из ${test.length}. Здесь нет автоматически оцениваемого ответа: оцените себя после сверки с источником.</p><h2>Воспроизведите по памяти ключевые определения, признаки и механизмы темы.</h2><textarea id="response" class="response" placeholder="Запишите всё, что помните, своими словами…"></textarea><div class="bottom"><button class="btn primary" id="reveal">Сверить с конспектом</button></div><div id="feedback"></div></div>`;$('#back').onclick=()=>lesson(current);$('#reveal').onclick=()=>{$('#feedback').innerHTML=`<div class="feedback"><strong>Фрагмент исходного материала</strong><p>${esc(q.why)}</p><p class="small muted">Сравните смысл, а не буквальное совпадение формулировок.</p><div class="bottom"><button class="btn primary" id="known">✓ Я это объяснил(а)</button><button class="btn" id="unknown">↻ Нужно повторить</button></div></div>`;$('#reveal').disabled=true;$('#known').onclick=()=>rateRecall(true);$('#unknown').onclick=()=>rateRecall(false)};scrollTo(0,0)}
function rateRecall(ok){if(ok)score++;else{review.push(test[idx]);difficult[current.uid]=true;persistStudy()}idx++;showQuestion()}
function answer(a){if(locked)return;locked=true;let q=test[idx],ok=a===q.correct;if(ok)score++;else review.push(q);document.querySelectorAll('[data-opt]').forEach(b=>{b.disabled=true;if(+b.dataset.opt===q.correct)b.classList.add('correct');else if(+b.dataset.opt===a)b.classList.add('wrong')});$('#feedback').innerHTML=`<div class="feedback"><strong>${ok?'✓ Верно!':'✕ Не совсем. Разберём ошибку.'}</strong><p>${esc(q.why)}</p>${!ok?`<p class="small">💡 Подсказка: вернитесь к интерактивной схеме и научному объяснению. Правильный вариант подсвечен зелёным.</p><button class="btn" id="revise">Повторить теорию</button>`:''}</div>`;if(!ok)$('#revise').onclick=()=>lesson(current);$('#next').style.display='inline-block'}
function finish(){let percent=Math.round(score/test.length*100);if(percent>=70){progress[current.uid]=true;save()}app.innerHTML=`<button class="back" id="back">← К темам</button><div class="panel result"><div class="eyebrow">РЕЗУЛЬТАТ</div><div class="score">${percent}%</div><h1>${percent>=70?'Хороший результат!':'Продолжим тренировку'}</h1><p class="muted">Правильных ответов: ${score} из ${test.length}. ${percent>=70?'Результат сохранён на этом устройстве.':'Для зачёта темы необходимо набрать минимум 70%.'} ${current.custom?'Вопросы составлены для этой темы.':'Оценка основана на вашей самопроверке, а не на автоматической проверке знаний.'}</p><div class="bottom" style="justify-content:center"><button class="btn primary" id="retry">Пройти ещё раз ↻</button><button class="btn" id="theory">Вернуться к лекции</button><button class="btn" id="home">Все темы</button></div></div>`;$('#back').onclick=home;$('#home').onclick=home;$('#retry').onclick=()=>startTest(current);$('#theory').onclick=()=>lesson(current);scrollTo(0,0)}

// v2: navigation, exam simulator, accessible source-backed active recall and study statistics.

function dueCount(){return Object.entries(spaced).filter(([k,v])=>v.due<=Date.now()).length}
function installExtras(){
 const bar=document.createElement('nav');bar.className='global-nav';bar.setAttribute('aria-label','Разделы приложения');
 bar.innerHTML='<button id="nav-home">⌂ Темы</button><button id="nav-tickets">▦ Билеты</button><button id="nav-bank">✦ Тренажёр</button><button id="nav-exam">◈ Экзамен</button><button id="nav-stats">▤ Статистика</button><button id="nav-due">◷ Повторение</button>';
 document.querySelector('header').after(bar);
 bar.querySelector('#nav-home').onclick=()=>{filter='Все';query='';home()};
 bar.querySelector('#nav-exam').onclick=examSetup;
 bar.querySelector('#nav-bank').onclick=bankHome;
 bar.querySelector('#nav-tickets').onclick=()=>ticketLibrary();
 bar.querySelector('#nav-stats').onclick=statistics;
 bar.querySelector('#nav-due').onclick=dueReview;
}
function home(){baseHome();let h=document.querySelector('.hero');if(h){const note=document.createElement('div');note.className='dashboard-note';note.innerHTML=`<b>Сегодня к повторению: ${dueCount()}</b><span>Готовьтесь по темам или пройдите смешанный экзамен по всему конспекту.</span><button class="btn primary" id="go-exam">Режим экзамена →</button>`;h.after(note);note.querySelector('#go-exam').onclick=examSetup;const train=document.createElement('button');train.className='btn primary';train.textContent='✦ Предметный тренажёр';train.onclick=bankHome;note.append(train)}}
function lesson(t){baseLesson(t);const lecture=document.querySelector('#lecture');if(lecture){const nav=document.createElement('div');nav.className='lecture-tools';nav.innerHTML='<button class="btn" id="font-down" aria-label="Уменьшить шрифт">A−</button><button class="btn" id="font-up" aria-label="Увеличить шрифт">A+</button><button class="btn" id="print-lesson">⎙ Печать</button><button class="btn" id="copy-lesson">⧉ Копировать</button>';lecture.before(nav);let font=16;try{font=Number(sessionStorage.getItem('micro-font')||16)}catch(e){}lecture.style.fontSize=font+'px';nav.querySelector('#font-down').onclick=()=>{font=Math.max(14,font-1);lecture.style.fontSize=font+'px';(()=>{try{sessionStorage.setItem('micro-font',font)}catch(e){}})()};nav.querySelector('#font-up').onclick=()=>{font=Math.min(23,font+1);lecture.style.fontSize=font+'px';(()=>{try{sessionStorage.setItem('micro-font',font)}catch(e){}})()};nav.querySelector('#print-lesson').onclick=()=>window.print();nav.querySelector('#copy-lesson').onclick=async()=>{try{await navigator.clipboard.writeText(t.title+'\n\n'+lecture.textContent);nav.querySelector('#copy-lesson').textContent='✓ Скопировано'}catch(e){alert('Копирование недоступно в этом браузере')}}}
 const bottom=document.querySelector('.bottom');if(bottom){const next=topics[t.uid+1];if(next){let b=document.createElement('button');b.className='btn';b.textContent='Следующая тема →';b.onclick=()=>lesson(next);bottom.append(b)}}
}
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function examSetup(){current=null;app.innerHTML=`<button class="back" id="back">← Все темы</button><div class="eyebrow">ТРЕНИРОВОЧНЫЙ ЭКЗАМЕН</div><h1>Проверьте себя перед зачётом</h1><div class="panel"><p class="muted">Вопросы из разных тем. Там, где есть проверенные варианты ответов, выбирайте один вариант; для остальных заданий самостоятельно сформулируйте ответ и сравните его с исходным конспектом. Самооценка не заменяет проверку преподавателя.</p><label class="field-label" for="exam-count">Количество заданий</label><select id="exam-count" class="field-select"><option value="10">10 · Быстрая тренировка</option><option value="20" selected>20 · Стандартный экзамен</option><option value="30">30 · Полный экзамен</option></select><label class="field-label" for="exam-section">Раздел</label><select id="exam-section" class="field-select">${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><div class="bottom"><button class="btn primary" id="begin-exam">Начать экзамен →</button></div></div>`;$('#back').onclick=home;$('#begin-exam').onclick=()=>startExam(Number($('#exam-count').value),$('#exam-section').value);scrollTo(0,0)}
let examQuestions=[],examAt=0,examCorrect=0,examMistakes=[],examCurrent=null;
function startExam(count,section){const pool=shuffle(topics.filter(t=>section==='Все'||t.section===section));if(!pool.length)return;examQuestions=[];let j=0;while(examQuestions.length<count&&j<count*3){let t=pool[j%pool.length],q=shuffle(buildQuestions(t))[0];if(q)examQuestions.push({...q,topic:t});j++}examAt=0;examCorrect=0;examMistakes=[];examQuestion()}
function examQuestion(){if(examAt>=examQuestions.length)return examFinish();const q=examQuestions[examAt];examCurrent=q.topic;const progressBar=`<div class="progress"><div style="width:${100*examAt/examQuestions.length}%"></div></div>`;let answer=q.type==='choice'?`<div class="options">${shuffle(q.options.map((o,i)=>({o,i}))).map(x=>`<button class="option" data-exam-choice="${x.i}">${esc(x.o)}</button>`).join('')}</div>`:`<textarea class="response" id="exam-response" placeholder="Вспомните определение и объясните механизм своими словами…"></textarea><button class="btn primary" id="exam-reveal">Показать ответ из конспекта</button>`;
 app.innerHTML=`<button class="back" id="exit-exam">← Завершить тренировку</button><div class="eyebrow">ЭКЗАМЕН · ${examAt+1} / ${examQuestions.length}</div><h2>${esc(q.topic.title)}</h2>${progressBar}<div class="question"><h2>${esc(q.type==='choice'?q.text:'Вспомните ключевое положение: '+q.text)}</h2>${answer}<div id="exam-feedback" aria-live="polite"></div></div>`;$('#exit-exam').onclick=examSetup;
 function mark(ok){if(ok)examCorrect++;else{examMistakes.push(q);difficult[q.topic.uid]=true;persistStudy()}const next=document.createElement('button');next.className='btn primary';next.textContent=examAt===examQuestions.length-1?'Результат →':'Следующий вопрос →';next.onclick=()=>{examAt++;examQuestion()};$('#exam-feedback').append(next)}
 if(q.type==='choice'){document.querySelectorAll('[data-exam-choice]').forEach(b=>b.onclick=()=>{const chosen=Number(b.dataset.examChoice),ok=chosen===q.correct;document.querySelectorAll('[data-exam-choice]').forEach(x=>{x.disabled=true;if(Number(x.dataset.examChoice)===q.correct)x.classList.add('correct');else if(x===b)x.classList.add('wrong')});$('#exam-feedback').innerHTML=`<div class="feedback"><b>${ok?'✓ Верно':'✕ Ошибка'}</b><p>${esc(q.why)}</p></div>`;mark(ok)})}
 else $('#exam-reveal').onclick=()=>{$('#exam-reveal').remove();$('#exam-feedback').innerHTML=`<div class="feedback"><b>Ответ по исходному конспекту</b><p>${esc(q.why)}</p><p class="muted small">Оцените смысловую точность самостоятельно.</p><div class="bottom"><button class="btn" id="exam-no">↻ Повторить</button><button class="btn" id="exam-yes">✓ Вспомнил</button></div></div>`;$('#exam-no').onclick=()=>{$('#exam-no').disabled=true;$('#exam-yes').disabled=true;mark(false)};$('#exam-yes').onclick=()=>{$('#exam-no').disabled=true;$('#exam-yes').disabled=true;mark(true)}};
 scrollTo(0,0)
}
function examFinish(){const pct=Math.round(examCorrect/Math.max(1,examQuestions.length)*100);app.innerHTML=`<div class="panel result"><div class="eyebrow">ТРЕНИРОВКА ЗАВЕРШЕНА</div><div class="score">${pct}%</div><h1>${examCorrect} из ${examQuestions.length}</h1><p class="muted">Это результат тренировки, часть ответов оценена вами самостоятельно. ${examMistakes.length?'Темы, требующие повторения, добавлены в список сложных.':'Вы не отметили ошибок.'}</p><div class="bottom" style="justify-content:center"><button class="btn primary" id="exam-again">Ещё один экзамен</button><button class="btn" id="exam-home">К темам</button></div></div>`;$('#exam-again').onclick=examSetup;$('#exam-home').onclick=home}
function statistics(){const total=topics.length,done=topics.filter(t=>progress[t.uid]).length,hard=topics.filter(t=>difficult[t.uid]).length,book=topics.filter(t=>bookmarks[t.uid]).length;app.innerHTML=`<button class="back" id="stats-back">← Все темы</button><div class="eyebrow">ЛИЧНАЯ СТАТИСТИКА</div><h1>Ваш прогресс</h1><div class="stat-grid"><div class="stat"><strong>${done}/${total}</strong><small>пройдено тем</small></div><div class="stat"><strong>${hard}</strong><small>требуют повторения</small></div><div class="stat"><strong>${dueCount()}</strong><small>карточек на сегодня</small></div><div class="stat"><strong>${book}</strong><small>избранных тем</small></div></div><div class="panel"><h2>Освоение разделов</h2>${categories.slice(1).map(c=>{let a=topics.filter(t=>t.section===c),d=a.filter(t=>progress[t.uid]).length;return `<div class="stat-line"><div><b>${esc(c)}</b><span>${d} / ${a.length}</span></div><div class="progress"><div style="width:${a.length?100*d/a.length:0}%"></div></div></div>`}).join('')}<p class="muted small">Зачёт темы основан на результате теста или самостоятельной оценке по конспекту.</p><div class="bottom"><button class="btn primary" id="stats-exam">Проверить знания →</button><button class="btn" id="stats-export">Экспорт прогресса</button></div></div>`;$('#stats-back').onclick=home;$('#stats-exam').onclick=examSetup;$('#stats-export').onclick=exportProgress;scrollTo(0,0)}
function dueReview(){const list=topics.filter(t=>excerpts(t).some((_,i)=>!spaced[t.uid+':'+i]||spaced[t.uid+':'+i].due<=Date.now()));app.innerHTML=`<button class="back" id="due-back">← Все темы</button><div class="eyebrow">ИНТЕРВАЛЬНОЕ ПОВТОРЕНИЕ</div><h1>Карточки для повторения</h1><p class="muted">Выберите тему, чтобы повторить карточки, срок которых наступил. Для новых тем карточки также доступны.</p><div class="tiles">${list.map(t=>`<button class="tile" data-due="${t.uid}"><div class="number">${esc(t.section)}</div><h3>${esc(t.title)}</h3><small>${excerpts(t).filter((_,i)=>!spaced[t.uid+':'+i]||spaced[t.uid+':'+i].due<=Date.now()).length} карточек</small></button>`).join('')}</div>`;$('#due-back').onclick=home;document.querySelectorAll('[data-due]').forEach(b=>b.onclick=()=>showFlashcards(topics.find(t=>t.uid==b.dataset.due),true));scrollTo(0,0)}

// Full exam-ticket archive reconstructed from explicit ticket headings in the user's PDF.
// This is source text, not a scientifically edited paraphrase.
// Identify top-level questions conservatively. Missing headings remain explicit rather than invented.
function ticketSections(t){
 const text=t.text;const candidates=[];
 const re=/^([1-3])[.)]\s*([^\n]{5,190})/gm;let m;
 while((m=re.exec(text))!==null){
  const label=m[2].trim();const n=Number(m[1]);
  if(label.length<9||/^(?:[А-ЯЁа-яё\w]+\s+){0,2}(?:растут|культивируются|развиваются|обладают|размножаются)\b/i.test(label))continue;
  candidates.push({number:n,title:m[0].trim(),start:m.index});
 }
 const found=[];let after=-1;
 for(let n=1;n<=3;n++){
  const a=candidates.find(c=>c.number===n&&c.start>after&&(n===1?c.start<500:true));
  if(a){found.push(a);after=a.start}
 }
 return found.map((c,i)=>({number:c.number,title:c.title,text:text.slice(c.start,(found[i+1]||{start:text.length}).start).trim()}));
}
function ticketHeadings(t){return ticketSections(t).map(s=>s.title)}
function ticketProgressRead(){try{return JSON.parse(localStorage.getItem('micro-ticket-progress')||'{}')}catch(e){return {}}}
let ticketProgress=ticketProgressRead();
function saveTicketProgress(){try{localStorage.setItem('micro-ticket-progress',JSON.stringify(ticketProgress))}catch(e){}}
function ticketStats(n){const p=ticketProgress[n]||{};return Object.values(p).filter(x=>x==='known').length}
function ticketLibrary(search=''){
 current=null;
 const list=TICKETS.filter(t=>('Билет '+t.number+' '+t.text).toLowerCase().includes(search.toLowerCase()));
 app.innerHTML=`<button class="back" id="ticket-back">← Темы</button><div class="eyebrow">ПЕРВОИСТОЧНИК · 27 БИЛЕТОВ</div><h1>Экзаменационные билеты</h1><p class="muted">Все 27 билетов выделены по заголовкам в загруженном PDF. Текст сохранён в порядке оригинала. Это архив для сверки, а не отредактированная научная лекция.</p><input id="ticket-search" class="search" aria-label="Поиск по билетам" placeholder="Номер билета или слово из конспекта" value="${esc(search)}"><div class="ticket-grid">${list.map(t=>`<button class="tile" data-ticket="${t.number}"><div class="number">БИЛЕТ ${t.number}</div><h3>${esc(ticketHeadings(t)[0]||'Материалы билета')}</h3><small>${ticketSections(t).length} выделено · ${ticketStats(t.number)} вспомнил · полный текст</small></button>`).join('')}</div>${list.length?'':'<p class="empty">По запросу билеты не найдены</p>'}`;
 $('#ticket-back').onclick=home;
 const dashboard=document.createElement('button');dashboard.className='btn primary';dashboard.textContent='▤ Прогресс по 27 билетам';dashboard.onclick=ticketDashboard;$('#ticket-search').before(dashboard);
 const inp=$('#ticket-search');inp.oninput=()=>{const pos=inp.selectionStart;ticketLibrary(inp.value);const next=$('#ticket-search');next.focus();next.setSelectionRange(pos,pos)};
 document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=()=>ticketView(Number(b.dataset.ticket)));
 scrollTo(0,0)
}
function ticketView(n){
 const t=TICKETS.find(t=>t.number===n);if(!t)return;
 const heads=ticketHeadings(t);
 app.innerHTML=`<button class="back" id="ticket-back">← Все билеты</button><div class="eyebrow">ОРИГИНАЛЬНЫЙ КОНСПЕКТ · БИЛЕТ ${n} ИЗ 27</div><h1>Билет № ${n}</h1><div class="study-shortcuts"><button class="btn" id="ticket-practice">✎ Устный экзамен по билету</button><button class="btn" id="ticket-copy">⧉ Копировать билет</button></div><div class="panel"><h2>Вопросы билета</h2>${heads.length?heads.map(h=>`<p class="ticket-heading">${esc(h)}</p>`).join(''):'<p class="muted">Вопросы см. в исходном тексте.</p>'}<p class="source">Источник: загруженный PDF. Перенос строк и некоторые обозначения могли измениться при извлечении текста.</p></div><div class="panel ticket-source"><h2>Текст из PDF</h2><div class="lecture">${esc(t.text)}</div></div><div class="bottom"><button class="btn" id="ticket-prev" ${n===1?'disabled':''}>← Билет ${n-1}</button><button class="btn primary" id="ticket-next" ${n===27?'disabled':''}>Билет ${n+1} →</button></div>`;
 $('#ticket-back').onclick=()=>ticketLibrary();$('#ticket-practice').onclick=()=>ticketPractice(n);
 $('#ticket-copy').onclick=async()=>{try{await navigator.clipboard.writeText('Билет '+n+'\n'+t.text);$('#ticket-copy').textContent='✓ Скопировано'}catch(e){alert('Не удалось скопировать')}};
 $('#ticket-prev').onclick=()=>ticketView(n-1);$('#ticket-next').onclick=()=>ticketView(n+1);scrollTo(0,0)
}
function ticketPractice(n){
 const t=TICKETS.find(x=>x.number===n),sections=ticketSections(t);
 let at=0;const questions=sections.length?sections:[{number:1,title:'Перескажите билет № '+n,text:t.text}];
 function draw(){
 if(at>=questions.length){const known=ticketStats(n);app.innerHTML=`<button class="back" id="back">← К билету</button><div class="panel result"><div class="eyebrow">БИЛЕТ ${n} · САМОПРОВЕРКА</div><h1>${known} из ${questions.length}</h1><p class="muted">Столько вопросов вы отметили как воспроизведённые. Это самостоятельная оценка, а не результат автоматической проверки.</p><div class="bottom" style="justify-content:center"><button class="btn primary" id="again">Повторить билет</button><button class="btn" id="to-ticket">Открыть конспект</button></div></div>`;$('#back').onclick=()=>ticketView(n);$('#again').onclick=()=>ticketPractice(n);$('#to-ticket').onclick=()=>ticketView(n);return}
 const q=questions[at];const prev=ticketProgress[n]?.[q.number];
 app.innerHTML=`<button class="back" id="back">← К билету</button><div class="eyebrow">УСТНЫЙ ЭКЗАМЕН · БИЛЕТ ${n} · ${at+1}/${questions.length}</div><div class="progress"><div style="width:${at/questions.length*100}%"></div></div><div class="panel"><h2>${esc(q.title)}</h2><p class="muted">Вспомните определения, классификации, механизмы и примеры. Сформулируйте ответ до открытия источника.</p><textarea id="ticket-answer" class="response" aria-label="Мой ответ" placeholder="Ключевые тезисы моего ответа…"></textarea><div class="bottom"><button class="btn primary" id="show-source">Сверить с конспектом</button></div><div id="source-reveal" aria-live="polite"></div>${prev?`<p class="small muted">Предыдущая оценка: ${prev==='known'?'вспомнил':'повторить'}</p>`:''}</div>`;
 $('#back').onclick=()=>ticketView(n);$('#show-source').onclick=()=>{$('#show-source').disabled=true;$('#source-reveal').innerHTML=`<div class="feedback"><h3>Материал именно к этому вопросу</h3><div class="ticket-excerpt">${esc(q.text)}</div><p class="small muted">Текст автоматически выделен из PDF по заголовкам. При неудачном разделении проверьте полный билет. Оцените смысл ответа самостоятельно.</p><div class="bottom"><button class="btn" id="ticket-hard">↻ Нужно повторить</button><button class="btn primary" id="ticket-known">✓ Вспомнил</button></div></div>`;
 function rate(v){ticketProgress[n]??={};ticketProgress[n][q.number]=v;saveTicketProgress();at++;draw()}
 $('#ticket-hard').onclick=()=>rate('hard');$('#ticket-known').onclick=()=>rate('known')};
 scrollTo(0,0)
 }draw()
}
function ticketDashboard(){
 const known=TICKETS.reduce((sum,t)=>sum+ticketStats(t.number),0);const all=TICKETS.reduce((sum,t)=>sum+ticketSections(t).length,0);
 app.innerHTML=`<button class="back" id="back">← К билетам</button><div class="eyebrow">ПОДГОТОВКА К УСТНОМУ ЭКЗАМЕНУ</div><h1>Контроль билетов</h1><p class="muted">Оценка сохраняется только на устройстве. Вопрос считается освоенным, если вы сами отметили «Вспомнил» после сверки с исходным конспектом.</p><div class="stats"><div class="stat"><strong>${known}/${all}</strong><small>вопросов вспомнил</small></div><div class="stat"><strong>${TICKETS.filter(t=>ticketStats(t.number)===ticketSections(t).length).length}/27</strong><small>билетов повторено</small></div></div><div class="ticket-grid">${TICKETS.map(t=>{const s=ticketSections(t),k=ticketStats(t.number);return `<button class="tile" data-practice="${t.number}"><div class="number">БИЛЕТ ${t.number}</div><h3>${k} / ${s.length} вопросов</h3><div class="progress"><div style="width:${s.length?100*k/s.length:0}%"></div></div><small>${k===s.length?'Самопроверка завершена':'Продолжить повторение'}</small></button>`}).join('')}</div>`;
 $('#back').onclick=()=>ticketLibrary();document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>ticketPractice(Number(b.dataset.practice)));scrollTo(0,0)
}

